"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Bottom Navigation: generated by UIX from the design system. Same variants and sizes as the Figma component.

const bottomNavVariants = cva(
  "flex w-full items-stretch h-[72px] px-2 pb-2",
  {
    variants: {
      theme: {
        light: "bg-surface border-t border-line-subtle [&_[aria-current=page]_[data-slot=pill]]:bg-brand-subtle [&_[aria-current=page]_[data-slot=pill]]:text-icon-brand [&_[aria-current=page]]:text-fg-brand",
        dark: "skin-keep bg-inverse text-fg-inverse [&_[aria-current=page]_[data-slot=pill]]:bg-brand [&_[aria-current=page]_[data-slot=pill]]:text-fg-on-brand [&_a:not([aria-current=page])]:opacity-70",
      },
    },
    defaultVariants: {
      theme: "light",
    },
  },
);

export interface BottomNavProps
  extends React.HTMLAttributes<HTMLElement>,
    VariantProps<typeof bottomNavVariants> {}

const BottomNav = React.forwardRef<HTMLElement, BottomNavProps>(
  ({ className, theme, ...props }, ref) => (
    <nav data-slot="bottom-nav" data-kind="surface" ref={ref} aria-label="Primary" className={cn(bottomNavVariants({ theme }), className)} {...props} />
  ),
);
BottomNav.displayName = "BottomNav";

export interface BottomNavItemProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Icon above the label. */
  icon: React.ReactNode;
  /** Marks the current tab. */
  active?: boolean;
}

const BottomNavItem = React.forwardRef<HTMLAnchorElement, BottomNavItemProps>(({ className, icon, active = false, children, ...props }, ref) => (
  <a ref={ref} data-slot="bottom-nav-item" aria-current={active ? "page" : void 0} className={cn("flex flex-1 flex-col items-center justify-center gap-1 text-label-small focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus rounded-md", className)} {...props}>
    <span data-slot="pill" className="inline-flex items-center justify-center rounded-full transition-colors w-[56px] h-[28px] [&_svg]:size-5">{icon}</span>
    <span>{children}</span>
  </a>
));
BottomNavItem.displayName = "BottomNavItem";

export { BottomNav, BottomNavItem, bottomNavVariants };
